<script setup lang="ts">
import {computed,defineAsyncComponent} from 'vue'
import {milliseconds,stageNames,timingSource,type OperationsPerformance} from '../../operations'
import Panel from '../../components/ui/Panel.vue'
import DataTable from '../../components/ui/DataTable.vue'
const props=defineProps<{data:OperationsPerformance;hours:number}>()
const Trend=defineAsyncComponent(()=>import('./OperationsTrend.vue'))
const ranked=computed(()=>(['desktop','backend'] as const).flatMap(source=>props.data.stages.filter(v=>v.source===source).sort((a,b)=>(b.p95Ms??-1)-(a.p95Ms??-1))).map(v=>({...v,id:`${v.stage}:${v.source}`})))
const stages=[{key:'stage',title:'阶段'},{key:'source',title:'来源'},{key:'count',title:'样本'},{key:'p50Ms',title:'P50'},{key:'p95Ms',title:'P95'},{key:'p99Ms',title:'P99'}]
const comparisons=[{key:'model',title:'模型'},{key:'appVersion',title:'客户端版本'},{key:'count',title:'样本数'},{key:'p95Ms',title:'P95'}]
const explanation=computed(()=>{const d=props.data;return d.percentileMethod==='histogram_upper_bound'?'阶段表分位数来自监控数据库直方图桶上界估算，与近期明细统计口径不同。':d.percentileMethod==='exact'?'阶段表分位数来自明细精确统计。':d.percentileMethod==='unknown'?'分位数统计口径未知。':props.hours>168?'超过 7 天的趋势可能来自监控直方图估算，与近期明细统计口径不同。':''})
const storage=computed(()=>{const d=props.data;return d.trendSource==='prometheus'?'趋势来自 Prometheus，P95 按直方图桶插值估算，与阶段表桶上界不是同一口径。':d.trendSource==='operations_database'?`趋势来源：监控数据库${d.percentileMethod==='exact'?'，明细精确分位数':d.percentileMethod==='histogram_upper_bound'?'，直方图桶上界估算':'，统计口径未知'}。`:'趋势存储来源未知。'})
</script>
<template><Panel title="回答延迟趋势" class="business-panel reveal"><p class="business-caption">每个时间段单独计算分位数，不平均分位数；低样本指标仅供参考。{{explanation}} {{storage}} 首段正文统计来源：{{timingSource(data.firstContentSource)}}；图例按各数据点实际来源标记。</p><Trend v-if="data.trend.length" :trend="data.trend" :first-content-source="data.firstContentSource" /><p v-else class="business-caption">暂无趋势样本。</p></Panel><p class="business-caption">客户端与后端分别排序，不跨时钟比较；RAG 与联网检索可能并行，阶段耗时不能直接相加。</p><Panel title="慢阶段排行" meta="各来源内按 P95 降序" class="reveal"><DataTable :columns="stages" :data="ranked" :min-width="760" empty-text="暂无阶段样本。"><template #cell-stage="{row}">{{stageNames[row.stage as keyof typeof stageNames]}}</template><template #cell-source="{row}">{{row.source==='desktop'?'客户端报告':'后端测量'}}</template><template #cell-count="{row}">{{row.count}}<span v-if="row.count<20" class="business-caption"> · 低样本</span></template><template #cell-p50Ms="{row}">{{milliseconds(row.p50Ms)}}</template><template #cell-p95Ms="{row}">{{milliseconds(row.p95Ms)}}</template><template #cell-p99Ms="{row}">{{row.count<100?'样本不足 100':milliseconds(row.p99Ms)}}</template></DataTable></Panel><Panel title="模型与版本对比" :meta="data.comparisonHours?`最近 ${data.comparisonHours} 小时`:undefined" class="reveal"><DataTable :columns="comparisons" :data="data.comparisons.map(v=>({...v,id:`${v.model}:${v.appVersion}`}))" :min-width="600" empty-text="暂无对比样本。"><template #cell-model="{row}">{{row.model||'未知'}}</template><template #cell-appVersion="{row}">{{row.appVersion||'未知'}}</template><template #cell-count="{row}">{{row.count}}{{row.count<20?' · 低样本':''}}</template><template #cell-p95Ms="{row}">{{milliseconds(row.p95Ms)}}</template></DataTable></Panel></template>
